type Offer = Record<string,unknown>;
const RETENTION_DAY=86400000;
// An explicit closing date always wins, even when it is months away.
// Sin cierre explícito, la antigüedad NO es cierre: conservar la oferta y marcarla para revalidación.
export function confirmedOfferDeadline(item:Offer):number | null {
  const explicit=Date.parse(String(item.sourceValidThrough || ''));
  if (Number.isFinite(explicit)) return explicit;
  // Legacy editions generated expiresAt at 20, 30 or 45 days. This is
  // NOT evidence of an employer deadline; only explicit source evidence counts.
  const expiry=Date.parse(String(item.expiresAt || ''));
  if(Number.isFinite(expiry) && (item.validityMethod==='explicit_deadline' ||
      item.origin==='community'))return expiry;
  return null;
}

export function offerRetentionReason(item:Offer,now=Date.now()):string | null {
  if (item.active!==true) return item.closureReason ? String(item.closureReason) : 'source_record_inactive';
  const deadline=confirmedOfferDeadline(item);
  if (deadline!==null && deadline<now) return 'application_window_elapsed';
  // A verified, undated municipal OPEN index is a renewable visibility lease,
  // not an employer-announced application deadline. It must not stay forever.
  if (item.kind==='job_offer' && item.validityMethod==='municipal_open_status') {
    const proofUntil=Date.parse(String(item.municipalOpenEvidenceValidUntil||''));
    if (!Number.isFinite(proofUntil) || now>proofUntil)
      return 'municipal_open_status_needs_fresh_evidence';
  }
  // A fresh, independently verified OPEN application without original date
  // receives a renewable visibility lease. It is not an employer deadline.
  if(item.kind==='job_offer' && item.validityMethod==='verified_open_official_source'){
    const proofUntil=Date.parse(String(item.openOfficialEvidenceValidUntil||''));
    if(!Number.isFinite(proofUntil) || now>proofUntil)
      return 'verified_open_official_source_needs_fresh_evidence';
  }
  // Publication age is never proof of closure. Keep undated jobs visible
  // until an explicit employer deadline or a confirmed closure is recorded.
  if (item.kind==='job_offer' && (item.verified!==true || item.review===true)) return 'approval_or_quality_review_required';
  return null;
}

export function offerRecheckDue(item:Offer,now=Date.now()) {
  if (item.kind!=='job_offer') return false;
  const checked=Date.parse(String(item.lastVerifiedAt || item.externalVerifiedAt || item.verifiedAt || ''));
  return !Number.isFinite(checked) || checked>now || now-checked>RETENTION_DAY;
}

export function offerFirstVisibleAt(item:Offer) {
  const value=Date.parse(String(item.firstPublishedAt || item.createdAt || ''));
  return Number.isFinite(value) ? value : null;
}

import { createHash, timingSafeEqual } from 'node:crypto';

// High-entropy bearer tokens never need to be stored in plaintext.
// Legacy laboratory records remain manageable until removed by their owners.
export type OwnerCredential = { ownerHash?:string; ownerToken?:string };
export function ownerTokenDigest(token:string):string {
  return createHash('sha256').update('trabajo-cerca:publication-owner:v1:\0'+token).digest('hex');
}
export function mayManagePublication(record:OwnerCredential, candidate:unknown):boolean {
  if(typeof candidate!=='string'||candidate.length<12||candidate.length>180)return false;
  const digest=record.ownerHash || (record.ownerToken ? ownerTokenDigest(record.ownerToken) : '');
  if(!/^[a-f0-9]{64}$/.test(digest))return false;
  return timingSafeEqual(Buffer.from(digest,'hex'),Buffer.from(ownerTokenDigest(candidate),'hex'));
}

import { readPublicFeedPage } from './public-feed';

// Bounded per-runtime cache of public, already approved pages only.
// Importers, administration and the identity-reconciliation endpoint bypass it.
type PublicPage = Awaited<ReturnType<typeof readPublicFeedPage>>;
type ValidPage = NonNullable<PublicPage>;
type CachedPage = { page:ValidPage; savedAt:number };
const PUBLIC_TTL_MS = 20_000;
const EMERGENCY_STALE_MS = 180_000;
const MAX_ENTRIES = 40;
const ready = new Map<string,CachedPage>();
const running = new Map<string,Promise<PublicPage>>();

function gatewayUnavailable(cause:unknown):boolean {
  const message=cause instanceof Error ? cause.message : String(cause);
  return /AppDatabaseGatewayUnavailable|AppDatabaseQuotaExceeded|Rate Exceeded|insufficient capacity|throttl|timed?\s?out|ECONNRESET/i.test(message);
}

export function readCachedPublicPage(cursor?:string, fresh=false):Promise<PublicPage> {
  const key=cursor||'__first__';
  const previous=ready.get(key);
  if(!fresh && previous && Date.now()-previous.savedAt<PUBLIC_TTL_MS)
    return Promise.resolve(previous.page);
  const active=running.get(key);
  if(active)return active;
  const request=readPublicFeedPage(cursor)
    .then(page=>{
      if(page && Array.isArray(page.items) && page.items.length<=40 &&
        (!('degraded' in page) || page.degraded!==true)){
        ready.delete(key);
        ready.set(key,{page,savedAt:Date.now()});
        while(ready.size>MAX_ENTRIES){
          const oldest=ready.keys().next().value;
          if(!oldest)break;
          ready.delete(oldest);
        }
      }
      // A rebuilding manifest returns null without throwing. Preserve a recent,
      // previously approved page as a clearly provisional response.
      if(!page && !cursor && previous && Date.now()-previous.savedAt<EMERGENCY_STALE_MS){
        console.warn('PUBLIC_FEED_LAST_READABLE_CACHE '+JSON.stringify({page:'first',reason:'manifest_rebuilding',ageSeconds:Math.floor((Date.now()-previous.savedAt)/1000)}));
        return {...previous.page,degraded:true,feedRebuilding:true,feedState:'degraded_last_good',totalsProvisional:true,cacheAgeSeconds:Math.floor((Date.now()-previous.savedAt)/1000)};
      }
      return page;
    })
    .catch(cause=>{
      const last=ready.get(key);
      const age=last?Date.now()-last.savedAt:Infinity;
      if(last && age>=0 && age<EMERGENCY_STALE_MS && gatewayUnavailable(cause)){
        console.warn('PUBLIC_FEED_LAST_READABLE_CACHE '+JSON.stringify({
          page:cursor?'paginated':'first',ageSeconds:Math.floor(age/1000),
          reason:'database_gateway_unavailable',
        }));
        return {...last.page,degraded:true,feedRebuilding:true,
          feedState:'degraded_last_good',totalsProvisional:true,
          cacheAgeSeconds:Math.floor(age/1000)};
      }
      throw cause;
    })
    .finally(()=>{if(running.get(key)===request)running.delete(key);});
  running.set(key,request);
  return request;
}

import { db } from '@appdeploy/sdk';
import { createHash } from 'node:crypto';
import { publicOfferIdentity, publicFeedIdentity } from './public-source-adapters';

type FeedSource = string;
type Stored = Record<string, unknown>;
type Entry = { key:string; source:FeedSource; sourceId:string; item:Stored; projectionRevision?:string };
type Order = { time:number; key:string };
type Counts = { jobs:number; newJobs24h:number; newJobs7d:number; people:number; needs:number; services:number };
type Summary = {
  itemCount:number; totalJobOffers:number; totalVerifiedJobOffers:number;
  recentJobOffers24h:number; recentJobOffers7d:number;
  totalProvisionalJobOffers:number; communeStats:Record<string, Counts>;
  kindStats:Omit<Counts, 'newJobs24h' | 'newJobs7d'>;
};
type PageRef = { id:string; keys:string[]; identities?:Array<string | null>; first:Order; last:Order; refreshAt:number | null; summary:Summary; projectionRevision?:string };
type Manifest = Summary & { schema:2; updatedAt:string; pages:PageRef[]; pageCount:number };
type Build = Manifest & { source:FeedSource | 'complete'; nextToken?:string };
type Change = { source:FeedSource; sourceId:string; queuedAt:string };
type Control = Stored & { manifestId?:string };
type Projector = {
  revision?:string;
  reconcileManifestId?:string;
  project:(item:Stored & { id:string }) => Stored | null;
  refreshAt:(item:Stored) => number | null;
};

const PAGE_SIZE = 40;
const STEP_SIZE = 40;
const ITEM_BYTES = 230 * 1024;
const INPUT_BYTES = 900 * 1024;
const SOURCES:FeedSource[] = ['radar_jobs', 'community_posts'];

function allowedSource(source:string) {
  return SOURCES.includes(source) || /^radar_external_[a-f0-9]{32}$/.test(source);
}

function identity(item:Stored) {
  if (item.kind !== 'job_offer' || typeof item.url !== 'string') return null;
  if (typeof item.documentUnitKey==='string' && item.documentUnitVerified===true) {
    const unit=publicOfferIdentity(item.url,item.documentUnitKey);
    return unit ? createHash('sha256').update(unit).digest('hex') : null;
  }
  const equivalent = publicFeedIdentity(item.url);
  return equivalent ? createHash('sha256').update(equivalent).digest('hex') : null;
}

function bytes(value:unknown) {
  return Buffer.byteLength(JSON.stringify(value), 'utf8');
}

function checkSize(value:unknown) {
  if (bytes(value) > ITEM_BYTES) throw new Error('Public feed record exceeds safe byte limit; previous feed retained');
}

function chunks<T>(values:T[], envelope:(items:T[]) => unknown) {
  const result:T[][] = [];
  let batch:T[] = [];
  for (const value of values) {
    if (bytes(envelope([value])) > INPUT_BYTES) throw new Error('Public feed request exceeds safe byte limit');
    const next = [...batch, value];
    if (batch.length && (next.length > 500 || bytes(envelope(next)) > INPUT_BYTES)) {
      result.push(batch);
      batch = [];
    }
    batch.push(value);
  }
  if (batch.length) result.push(batch);
  return result;
}

async function single<T>(table:string) {
  return (await db.list<T>(table, { limit:1 })).items[0];
}

async function replaceSingle(table:string, record:Stored) {
  checkSize(record);
  const current = await single<Stored>(table);
  if (current) {
    const [ok] = await db.update(table, [{ id:current.id, record }]);
    if (!ok) throw new Error('Public feed pointer/checkpoint write failed: ' + table);
  } else {
    const [id] = await db.add(table, [record]);
    if (!id) throw new Error('Public feed pointer/checkpoint insert failed: ' + table);
  }
}

async function queueChanges(source:string, ids:string[]) {
  if (!allowedSource(source) || !ids.length) return;
  const records = ids.map(sourceId => ({ source, sourceId, queuedAt:new Date().toISOString() }));
  for (const batch of chunks(records, records => ({ table:'public_feed_changes', records }))) {
    const saved = await db.add('public_feed_changes', batch);
    if (saved.length !== batch.length || saved.some(id => !id)) {
      throw new Error('Source saved but public feed change registration failed; reconciliation required');
    }
  }
}

export async function registerPublicFeedChange(source:string, id:string) {
  if (!allowedSource(source) || !id) throw new Error('Invalid external feed source');
  await queueChanges(source, [id]);
}

// A rejected winner must not permanently hide its formerly deduplicated copies.
// Read immutable baseline references; requeue current originals, never old copies.
async function reconcileFeedEquivalents(projector:Projector) {
  if (!projector.reconcileManifestId || !projector.revision) return;
  const saved=await single<Stored>('public_feed_identity_policy');
  if (saved?.revision===projector.revision && saved?.baselineManifestId===projector.reconcileManifestId) return;
  const [baseline]=await db.get<Manifest>('public_feed_manifests',[projector.reconcileManifestId]);
  if (!baseline || baseline.pages.length>20 || baseline.pages.reduce((count,page)=>count+page.keys.length,0)>800) throw new Error('Identity reconciliation baseline unavailable or oversized');
  const groups=new Map<string,Entry[]>();
  for (const ref of baseline.pages) {
    const [leaf]=await db.get<{entries:Entry[]}>('public_feed_versions',[ref.id]);
    if (!leaf || leaf.entries.length>40) throw new Error('Identity reconciliation page unavailable');
    for (const entry of leaf.entries) {
      if (!allowedSource(entry.source) || !entry.sourceId || entry.key!==entry.source+':'+entry.sourceId) throw new Error('Identity reconciliation reference invalid');
      const key=identity(entry.item);
      if (key) groups.set(key,[...(groups.get(key)??[]),entry]);
    }
  }
  const wanted=new Map<string,Entry>();
  for (const members of groups.values()) if (members.length>1) for (const entry of members) wanted.set(entry.key,entry);
  for (const source of new Set([...wanted.values()].map(entry=>entry.source))) {
    await queueChanges(source,[...wanted.values()].filter(entry=>entry.source===source).map(entry=>entry.sourceId));
  }
  // A partial queue failure leaves this unset; retries are safe and idempotent.
  await replaceSingle('public_feed_identity_policy',{revision:projector.revision,baselineManifestId:projector.reconcileManifestId,
    queuedReferences:wanted.size,completedAt:new Date().toISOString()});
}

// Return the original per-item results. Never treat an array length as success.
export async function trackedFeedAdd(table:string, records:Stored[]) {
  const ids:Array<string | null> = [];
  for (const batch of chunks(records, records => ({ table, records }))) {
    batch.forEach(checkSize);
    const saved = await db.add(table, batch);
    if (saved.length !== batch.length) throw new Error('Source insertion result count mismatch');
    ids.push(...saved);
    await queueChanges(table, saved.filter((id):id is string => Boolean(id)));
  }
  return ids;
}

export async function trackedFeedUpdate(table:string, updates:Array<{ id:string; record:Stored }>) {
  const results:boolean[] = [];
  for (const batch of chunks(updates, items => ({ table, items }))) {
    batch.forEach(item => checkSize(item.record));
    const saved = await db.update(table, batch);
    if (saved.length !== batch.length) throw new Error('Source update result count mismatch');
    results.push(...saved);
    await queueChanges(table, batch.filter((_, i) => saved[i]).map(item => item.id));
  }
  return results;
}

export async function trackedFeedDelete(table:string, ids:string[]) {
  const results:boolean[] = [];
  for (const batch of chunks(ids, ids => ({ table, ids }))) {
    const saved = await db.delete(table, batch);
    if (saved.length !== batch.length) throw new Error('Source deletion result count mismatch');
    results.push(...saved);
    await queueChanges(table, batch.filter((_, i) => saved[i]));
  }
  return results;
}

function order(entry:Entry):Order {
  const time = Date.parse(String(entry.item.createdAt || ''));
  return { time:Number.isFinite(time) ? time : 0, key:entry.key };
}

function compare(a:Order, b:Order) {
  return b.time - a.time || a.key.localeCompare(b.key);
}

function emptySummary():Summary {
  return { itemCount:0, totalJobOffers:0, totalVerifiedJobOffers:0, totalProvisionalJobOffers:0,
    recentJobOffers24h:0,recentJobOffers7d:0,
    communeStats:{}, kindStats:{ jobs:0, people:0, needs:0, services:0 } };
}

function summarize(entries:Entry[], now:number):Summary {
  const summary = emptySummary();
  summary.itemCount = entries.length;
  for (const { item } of entries) {
    const kind = item.kind === 'job_offer' ? 'jobs' : item.kind === 'worker_available' ? 'people'
      : item.kind === 'worker_need' ? 'needs' : item.kind === 'service_request' ? 'services' : null;
    if (!kind) continue;
    summary.kindStats[kind]++;
    if (kind === 'jobs') {
      summary.totalJobOffers++;
      if (item.verified && !item.review) summary.totalVerifiedJobOffers++;
      const first=Date.parse(String(item.firstPublishedAt || item.createdAt || ''));
      if (first<=now && first>=now-86400000) summary.recentJobOffers24h++;
      if (first<=now && first>=now-7*86400000) summary.recentJobOffers7d++;
    }
    const places = Array.isArray(item.workCommunes) ? [...new Set(item.workCommunes.map(String))] : [];
    for (const place of places) {
      const stat = summary.communeStats[place] ??= { jobs:0, newJobs24h:0, newJobs7d:0, people:0, needs:0, services:0 };
      stat[kind]++;
      const first=Date.parse(String(item.firstPublishedAt || item.createdAt || ''));
      if (kind === 'jobs' && first<=now && first>=now-86400000) stat.newJobs24h++;
      if (kind === 'jobs' && first<=now && first>=now-7*86400000) stat.newJobs7d++;
    }
  }
  return summary;
}

function total(pages:PageRef[]):Summary {
  const result = emptySummary();
  for (const { summary } of pages) {
    result.itemCount += summary.itemCount;
    result.totalJobOffers += summary.totalJobOffers;
    result.totalVerifiedJobOffers += summary.totalVerifiedJobOffers;
    result.recentJobOffers24h += summary.recentJobOffers24h || 0;
    result.recentJobOffers7d += summary.recentJobOffers7d || 0;
    for (const kind of ['jobs', 'people', 'needs', 'services'] as const) result.kindStats[kind] += summary.kindStats[kind];
    for (const [place, counts] of Object.entries(summary.communeStats)) {
      const current = result.communeStats[place] ??= { jobs:0, newJobs24h:0, newJobs7d:0, people:0, needs:0, services:0 };
      for (const kind of ['jobs', 'newJobs24h', 'newJobs7d', 'people', 'needs', 'services'] as const) current[kind] += counts[kind] || 0;
    }
  }
  if (pages.some(page=>typeof page.summary.recentJobOffers7d!=='number')) {
    delete (result as Partial<Summary>).recentJobOffers7d;
    delete (result as Partial<Summary>).recentJobOffers24h;
    for (const stat of Object.values(result.communeStats)) delete (stat as Partial<Counts>).newJobs7d;
  }
  return result;
}

class Editor {
  private cache = new Map<PageRef, Entry[]>();
  private changed = new Set<PageRef>();
  public pages:PageRef[];
  private projector:Projector;
  private now:number;

  constructor(pages:PageRef[], projector:Projector, now:number) {
    this.pages = pages;
    this.projector = projector;
    this.now = now;
  }

  private async entries(ref:PageRef) {
    let entries = this.cache.get(ref);
    if (!entries) {
      const [page] = await db.get<{ entries:Entry[] }>('public_feed_versions', [ref.id]);
      if (!page) throw new Error('Public feed page missing; previous feed retained');
      entries = page.entries.map(entry => ({ ...entry, projectionRevision:entry.projectionRevision ?? ref.projectionRevision }));
      this.cache.set(ref, entries);
    }
    return entries;
  }

  private set(ref:PageRef, entries:Entry[]) {
    ref.keys = entries.map(entry => entry.key);
    ref.identities = entries.map(entry => identity(entry.item));
    if (entries.length) {
      ref.first = order(entries[0]);
      ref.last = order(entries[entries.length - 1]);
    }
    this.cache.set(ref, entries);
    this.changed.add(ref);
  }

  async put(source:FeedSource, sourceId:string, record:Stored | null) {
    const key = source + ':' + sourceId;
    const wasPublished=this.pages.find(page=>page.keys.includes(key));
    const projected=record ? this.projector.project({...record,id:sourceId}) : null;
    if(wasPublished && !projected && record?.kind==='job_offer' && record.verified===true &&
       record.review!==true){
      const previous=(await this.entries(wasPublished)).find(item=>item.key===key);
      const deadline=Date.parse(String(record.sourceValidThrough||''));
      const closure=String(record.closureReason||'');
      const municipalEvidenceUntil=Date.parse(String(record.municipalOpenEvidenceValidUntil||''));
      const municipalEvidenceExpired=record.validityMethod==='municipal_open_status' &&
        (!Number.isFinite(municipalEvidenceUntil)||municipalEvidenceUntil<this.now);
      const officialOpenEvidenceUntil=Date.parse(String(record.openOfficialEvidenceValidUntil||''));
      const officialOpenEvidenceExpired=record.validityMethod==='verified_open_official_source' &&
        (!Number.isFinite(officialOpenEvidenceUntil)||officialOpenEvidenceUntil<this.now);
      // Preserve a previously approved listing when its source becomes inactive
      // without a confirmed closure; this is a state discrepancy, not proof of closure.
      // Never restore the source's active flag automatically.
      const keep=previous?.item.verified===true && previous.item.review!==true &&
        (!Number.isFinite(deadline)||deadline>=this.now) &&
        !/confirmed|explicit|administrative|owner_request/.test(closure) &&
        !municipalEvidenceExpired && !officialOpenEvidenceExpired;
      if(keep){
        console.warn('PUBLIC_FEED_LAST_GOOD_PRESERVED '+JSON.stringify({source,sourceId}));
        return;
      }
    }
    const firstTimes:number[]=[];
    const remember=(value:Stored)=>{
      const time=Date.parse(String(value.firstPublishedAt || value.createdAt || ''));
      if (Number.isFinite(time) && time<=this.now) firstTimes.push(time);
    };
    const old = this.pages.find(ref => ref.keys.includes(key));
    if (old) {
      const current=await this.entries(old);
      const previous=current.find(entry=>entry.key===key);if (previous) remember(previous.item);
      const remaining = current.filter(entry => entry.key !== key);
      this.set(old, remaining);
      if (!remaining.length) this.pages.splice(this.pages.indexOf(old), 1);
    }
    const item = projected;
    if (!item) return;
    remember(item);
    const incomingIdentity = identity(item);
    if (incomingIdentity) {
      const duplicates = this.pages.filter(page => page.identities?.includes(incomingIdentity));
      for (const page of duplicates) for (const entry of await this.entries(page)) if (identity(entry.item)===incomingIdentity) remember(entry.item);
      for (const page of duplicates) {
        const existing = await this.entries(page);
        const duplicate = existing.find(entry => identity(entry.item) === incomingIdentity);
        if (!duplicate) throw new Error('Feed identity metadata mismatch');
        const approved = (value:Stored) => value.kind==='job_offer' &&
          value.verified===true && value.review!==true && value.active===true;
        // Never replace an approved duplicate with a pending/unverified copy,
        // even if the pending copy carries a newer verification timestamp.
        const preserveApproved = approved(duplicate.item) && !approved(item);
        // A later portal-city recheck must not replace a verified original
        // worksite merely because the portal recheck has a newer timestamp.
        const priorSites=duplicate.item.workCommunes;
        const nextSites=item.workCommunes;
        const priorEvidence=duplicate.item.workLocationEvidence;
        const nextEvidence=item.workLocationEvidence;
        const preserveVerifiedTerritory =
          approved(duplicate.item) && approved(item) &&
          Array.isArray(priorSites) && Array.isArray(nextSites) &&
          priorSites.length>0 && nextSites.length>0 &&
          JSON.stringify([...priorSites].sort())!==JSON.stringify([...nextSites].sort()) &&
          Boolean(priorEvidence) && !nextEvidence;
        const checked = (value:Stored) => {
          const stamp = Date.parse(String(value.externalVerifiedAt || value.verificationCheckedAt || value.verifiedAt || ''));
          return Number.isFinite(stamp) && stamp <= this.now ? stamp : 0;
        };
        if (preserveApproved || preserveVerifiedTerritory ||
            (approved(duplicate.item)===approved(item) && checked(duplicate.item) > checked(item))) {
          if (firstTimes.length) {duplicate.item={...duplicate.item,firstPublishedAt:new Date(Math.min(...firstTimes)).toISOString()};this.set(page,existing);}
          return;
        }
      }
      for (const page of duplicates) {
        const remaining = (await this.entries(page)).filter(entry => identity(entry.item) !== incomingIdentity);
        this.set(page, remaining);
        if (!remaining.length) this.pages.splice(this.pages.indexOf(page), 1);
      }
    }
    if (firstTimes.length) item.firstPublishedAt=new Date(Math.min(...firstTimes)).toISOString();
    const entry:Entry = { key, source, sourceId, item, ...(this.projector.revision ? { projectionRevision:this.projector.revision } : {}) };
    checkSize({ entries:[entry] });
    let ref = this.pages.find(page => compare(order(entry), page.last) <= 0) ?? this.pages[this.pages.length - 1];
    if (!ref) {
      ref = { id:'', keys:[], first:order(entry), last:order(entry), refreshAt:null, summary:emptySummary() };
      this.pages.push(ref);
      this.cache.set(ref, []);
    }
    const sorted = [...await this.entries(ref), entry].sort((a,b) => compare(order(a), order(b)));
    const groups:Entry[][] = [];
    const groupSize = sorted.length > PAGE_SIZE || bytes({ entries:sorted }) > ITEM_BYTES ? Math.ceil(sorted.length / 2) : PAGE_SIZE;
    let group:Entry[] = [];
    for (const value of sorted) {
      if (group.length && (group.length >= groupSize || bytes({ entries:[...group, value] }) > ITEM_BYTES)) {
        groups.push(group);
        group = [];
      }
      group.push(value);
    }
    if (group.length) groups.push(group);
    const index = this.pages.indexOf(ref);
    const replacements = groups.map((values, i) => {
      const next = i === 0 ? ref : { ...ref, id:'' };
      this.set(next, values);
      return next;
    });
    this.pages.splice(index, 1, ...replacements);
  }

  async upgrade(ref:PageRef) {
    this.set(ref, await this.entries(ref));
  }

  async persist() {
    for (const ref of this.pages.filter(page => this.changed.has(page))) {
      const entries = await this.entries(ref);
      const record = { entries };
      checkSize(record);
      const [id] = await db.add('public_feed_versions', [record]);
      if (!id) throw new Error('Public feed page insertion failed; previous feed retained');
      ref.id = id;
      if (this.projector.revision) {
        if (entries.every(entry => entry.projectionRevision === this.projector.revision)) ref.projectionRevision = this.projector.revision;
        else delete ref.projectionRevision;
      }
      ref.summary = summarize(entries, this.now);
      const times = entries.map(entry => this.projector.refreshAt(entry.item)).filter((value):value is number => value !== null && value > this.now);
      ref.refreshAt = times.length ? Math.min(...times) : null;
    }
    return this.pages;
  }
}

function manifest(pages:PageRef[], now:number):Manifest {
  const record:Manifest = { ...total(pages), schema:2, updatedAt:new Date(now).toISOString(),
    pages, pageCount:Math.max(1, pages.length) };
  checkSize(record);
  return record;
}

async function publish(record:Manifest, projector:Projector) {
  checkSize(record);
  // Prevent silent loss of previously approved jobs when a feed page is
  // reprojected. A confirmed source deadline or owner closure is allowed.
  const oldControl=await single<Control>('public_feed_control');
  const oldCount=Number(oldControl?.totalVerifiedJobOffers||0);
  const confirmedRemovals:Array<{key:string;reason:string}>=[];
  if(oldControl?.manifestId){
    const [baseline]=await db.get<Manifest>('public_feed_manifests',[oldControl.manifestId]);
    if(!baseline)throw new Error('Public feed regression: prior manifest missing');
    const oldEntries:Entry[]=[],newKeys=new Set<string>(),newVerifiedIdentities=new Set<string>();
    for(const page of baseline.pages){
      const [leaf]=await db.get<{entries:Entry[]}>('public_feed_versions',[page.id]);
      if(!leaf)throw new Error('Public feed regression: prior page missing');
      oldEntries.push(...leaf.entries);
    }
    for(const page of record.pages){
      const [leaf]=await db.get<{entries:Entry[]}>('public_feed_versions',[page.id]);
      if(!leaf)throw new Error('Public feed regression: proposed page missing');
      for(const entry of leaf.entries){
        newKeys.add(entry.key);
        if(entry.item.kind==='job_offer' && entry.item.verified===true && entry.item.review!==true){
          const equivalent=identity(entry.item);
          if(equivalent)newVerifiedIdentities.add(equivalent);
        }
      }
    }
    const missing=oldEntries.filter(entry=>entry.item.kind==='job_offer'&&
      entry.item.verified===true&&entry.item.review!==true&&!newKeys.has(entry.key)&&
      !(identity(entry.item) && newVerifiedIdentities.has(identity(entry.item)!)));
    const unexpected:string[]=[];
    // Read-only, bounded diagnostics. Never log raw private source records.
    const missingSourceDiagnostics:Record<string,unknown>[]=[];
    for(const lost of missing){
      const [source]=await db.get<Stored>(lost.source,[lost.sourceId]);
      const deadline=Date.parse(String(source?.sourceValidThrough||''));
      const expired=Number.isFinite(deadline)&&deadline<Date.now();
      const communityUntil=Date.parse(String(source?.expiresAt||''));
      const communityExpired=lost.source==='community_posts'&&Number.isFinite(communityUntil)&&communityUntil<Date.now();
      const closed=Boolean(source?.closureReason&&/confirmed|explicit|administrative|owner_request/.test(String(source.closureReason)));
      const municipalEvidenceUntil=Date.parse(String(source?.municipalOpenEvidenceValidUntil||''));
      const municipalEvidenceExpired=source?.validityMethod==='municipal_open_status' &&
        (!Number.isFinite(municipalEvidenceUntil)||municipalEvidenceUntil<Date.now());
      if(!expired&&!communityExpired&&!closed&&!municipalEvidenceExpired){
        unexpected.push(lost.key);
        if(missingSourceDiagnostics.length<10)missingSourceDiagnostics.push({
          key:lost.key,
          sourceExists:Boolean(source),
          sourceApproved:source?.verified===true && source?.review!==true,
          sourceActive:source?.active===true,
          workCommunesArray:Array.isArray(source?.workCommunes),
          workCommunesCount:Array.isArray(source?.workCommunes)?source.workCommunes.length:0,
          sourceDatePresent:Boolean(source?.sourcePublishedAt||source?.date||source?.firstPublishedAt),
          sourceUrlPresent:Boolean(source?.url),
          // Distinguish projection rejection from an ingestion/queue omission.
          projectionEligible:Boolean(source && source.verified===true && source.review!==true && source.active===true),
          sourceHasOriginalDate:Boolean(source?.sourcePublishedAt||source?.date),
          sourceHasFirstPublishedDate:Boolean(source?.firstPublishedAt),
          sourceHasTerritorialScope:Array.isArray(source?.workCommunes) && source.workCommunes.length>0,
          sourceProjectsToFeed:Boolean(source && projector.project({...source,id:lost.sourceId})),
          originalIdentityPresent:Boolean(identity(lost.item)),
          proposedEquivalentPresent:Boolean(identity(lost.item) && newVerifiedIdentities.has(identity(lost.item)!)),
          deadlineExpired:expired,
          closureConfirmed:closed
        });
      } else if (confirmedRemovals.length < 50) {
        confirmedRemovals.push({key:lost.key,
          reason:expired?'explicit_deadline':communityExpired?'community_expiry':
            closed?'confirmed_closure':'municipal_open_evidence_expired'});
      }
    }
    if(unexpected.length){
      console.warn('PUBLIC_FEED_REGRESSION_BLOCKED '+JSON.stringify({
        before:oldCount,after:record.totalVerifiedJobOffers,
        missing:missing.length,unexplained:unexpected.length,
        ids:unexpected.slice(0,20),
        missingSourceDiagnostics,
        diagnostics:missing.filter(entry=>unexpected.includes(entry.key)).slice(0,10).map(entry=>({
          key:entry.key,source:entry.source,sourceId:entry.sourceId,
          title:String(entry.item.title||'').slice(0,120),
          url:String(entry.item.url||'').slice(0,200),
          verified:entry.item.verified,review:entry.item.review,
          active:entry.item.active
        })),at:new Date().toISOString()}));
      return {...(await readPublicFeedSummary()),rebuilding:false,regressionBlocked:true};
    }
  }
  const [manifestId] = await db.add('public_feed_manifests', [record]);
  if (!manifestId) throw new Error('Public feed manifest insertion failed; previous feed retained');
  const previous = await single<Control>('public_feed_control');
  const { id:_id, ...fields } = previous ?? {};
  const { pages:_pages, ...summary } = record;
  // Keep a durable, independently readable pointer to the last complete manifest.
  // A backup failure must prevent publishing a pointer that cannot be recovered.
  // Retain the previous immutable manifest as an independent recovery target.
  // On the very first publication there is no prior manifest to retain.
  const backupId=previous?.manifestId || manifestId;
  // Never pair a prior manifest identifier with counts from a newer manifest.
  // Readers recover the authoritative totals directly from the immutable manifest.
  await replaceSingle('public_feed_last_good', { manifestId:backupId, updatedAt:new Date().toISOString() });
  await replaceSingle('public_feed_control', { ...fields, ...summary, manifestId });
  if(confirmedRemovals.length)console.warn('PUBLIC_FEED_CONFIRMED_REMOVALS '+JSON.stringify({
    before:oldCount,after:record.totalVerifiedJobOffers,
    items:confirmedRemovals,at:new Date().toISOString()}));
  return { ...summary, manifestId, rebuilding:false };
}

export async function readPublicFeedSummary() {
  const current = await single<Control>('public_feed_control');
  const fallback = current?.manifestId ? null : await single<Control>('public_feed_last_good');
  const manifestId = current?.manifestId || fallback?.manifestId;
  if (manifestId) {
    const [manifest] = await db.get<Manifest>('public_feed_manifests', [manifestId]);
    if (manifest) {
      const { pages:_pages, schema:_schema, ...summary } = manifest;
      return { ...emptySummary(), ...summary, manifestId, rebuilding:!current?.manifestId };
    }
  }
  return { ...emptySummary(), ...current, rebuilding:!current?.manifestId };
}

export async function currentPublicFeedManifest() {
  const current = await single<Control>('public_feed_control');
  const lastGood = await single<Control>('public_feed_last_good');
  const ids = [...new Set([current?.manifestId, lastGood?.manifestId].filter((id):id is string => typeof id==='string' && Boolean(id)))];
  for (const manifestId of ids) {
    const [record] = await db.get<Manifest>('public_feed_manifests', [manifestId]);
    if (record && Array.isArray(record.pages)) return { manifestId, manifest:record };
  }
  if (ids.length) throw new Error('Public feed manifest missing');
  return null;
}

export async function publicFeedProgress() {
  const current = await single<Control>('public_feed_control');
  const build = await single<Build>('public_feed_build_state');
  const identityPolicy=await single<Stored>('public_feed_identity_policy');
  // Read-only queue health: lets QA distinguish duplicate/already-visible offers
  // from unpublished changes without running the protected writer manually.
  const pending=await db.list<Change>('public_feed_changes',{limit:STEP_SIZE});
  const queuedAt=pending.items.map(item=>Date.parse(item.queuedAt || '')).filter(Number.isFinite);
  const oldestQueuedAt=queuedAt.length ? new Date(Math.min(...queuedAt)).toISOString() : null;
  return { pendingFeedChanges:pending.items.length, pendingFeedChangesAtLeast:pending.items.length===STEP_SIZE,
    oldestQueuedAt, queueSampleLimit:STEP_SIZE,
    complete:Boolean(current?.manifestId), manifestId:current?.manifestId ?? null,
    visibleItemCount:Number(current?.itemCount || 0), buildSource:build?.source ?? null,
    stagedPages:build?.pages?.length ?? 0, stagedPublicItems:build?.itemCount ?? 0,
    hasNextSourcePage:Boolean(build?.nextToken), updatedAt:current?.updatedAt ?? null,
    identityReconciliation:identityPolicy ? {revision:identityPolicy.revision,baselineManifestId:identityPolicy.baselineManifestId,
      queuedReferences:identityPolicy.queuedReferences,completedAt:identityPolicy.completedAt} : null };
}

// Read-only partial public projection during the initial multi-step feed build.
// Never expose private source rows or administrative candidates.
export async function readStagedPublicFeedPage() {
  const staged=await single<Build>('public_feed_build_state');
  if(!staged?.pages?.length)return null;
  // A valid staged page may be empty after filtering; find the first nonempty public page.
  let items:Stored[]=[];
  for(const ref of staged.pages){
    const [leaf]=await db.get<{entries:Entry[]}>('public_feed_versions',[ref.id]);
    if(!leaf || !Array.isArray(leaf.entries))continue;
    if(leaf.entries.length){items=leaf.entries.map(entry=>entry.item);break;}
  }
  if(!items.length)return null;
  // A staged build is incomplete: never present first-page counts as final totals.
  // Expose only the approved public projection already persisted in the leaf.
  const { pages:_pages, nextToken:_nextToken, source:_source, ...partial }=staged;
  return {...emptySummary(),...partial,items,
    totalItems:staged.itemCount,hasMore:false,
    additionalStagedPagesPending:staged.pages.length>1,
    stagedPages:staged.pages.length,
    feedRebuilding:true,degraded:true,feedState:'building_partial',
    totalsProvisional:true};
}

// Single scheduled writer: the existing verify-publish cron. Other handlers only read the summary.
export async function advancePublicFeed(projector:Projector) {
  const now = Date.now();
  const control = await single<Control>('public_feed_control');
  if (!control?.manifestId) {
    const saved = await single<Build>('public_feed_build_state');
    const build:Build = saved ?? { ...manifest([], now), source:'radar_jobs' };
    const legacy = build.pages.find(page => !Array.isArray(page.identities));
    if (legacy) {
      const editor = new Editor(build.pages, projector, now);
      await editor.upgrade(legacy);
      await replaceSingle('public_feed_build_state', { ...build, ...manifest(await editor.persist(), now) });
      return { ...await readPublicFeedSummary(), rebuilding:true, buildSource:build.source };
    }
    if (build.source === 'complete') {
      // External offers are stored in radar_external_* and only referenced by the
      // change queue. Include them in the FIRST manifest, not just later updates.
      const pending=await db.list<Change>('public_feed_changes',{limit:STEP_SIZE});
      if(pending.items.length){
        const editor=new Editor(build.pages,projector,now);
        const wanted=new Map<string,{source:string;sourceId:string}>();
        for(const change of pending.items){
          if(!allowedSource(change.source)||!change.sourceId)throw new Error('Invalid public feed change');
          wanted.set(change.source+':'+change.sourceId,change);
        }
        for(const source of new Set([...wanted.values()].map(item=>item.source))){
          const ids=[...wanted.values()].filter(item=>item.source===source).map(item=>item.sourceId);
          const records=await db.get<Stored>(source,ids);
          if(records.length!==ids.length)throw new Error('Source read result count mismatch');
          for(let i=0;i<ids.length;i++)await editor.put(source,ids[i],records[i]);
        }
        const pages=await editor.persist();
        await replaceSingle('public_feed_build_state',{...manifest(pages,now),source:'complete'});
        const result=await publish(manifest(pages,now),projector);
        if(!('regressionBlocked' in result && result.regressionBlocked)){
          const removed=await db.delete('public_feed_changes',pending.items.map(change=>change.id));
          if(removed.length!==pending.items.length||removed.some(ok=>!ok))throw new Error('Public feed change acknowledgement failed');
        }
        return result;
      }
      return publish(manifest(build.pages, now), projector);
    }
    const rows = await db.list<Stored>(build.source, { limit:STEP_SIZE, ...(build.nextToken ? { nextToken:build.nextToken } : {}) });
    const editor = new Editor(build.pages, projector, now);
    for (const { id, ...record } of rows.items) await editor.put(build.source, id, record);
    const pages = await editor.persist();
    const source = rows.nextToken ? build.source : build.source === 'radar_jobs' ? 'community_posts' : 'complete';
    const next:Build = { ...manifest(pages, now), source, ...(rows.nextToken ? { nextToken:rows.nextToken } : {}) };
    await replaceSingle('public_feed_build_state', next as unknown as Stored);
    return source === 'complete' ? advancePublicFeed(projector) : { ...await readPublicFeedSummary(), rebuilding:true, buildSource:source };
  }

  const [current] = await db.get<Manifest>('public_feed_manifests', [control.manifestId]);
  if (!current) throw new Error('Public feed manifest missing; previous feed retained');
  await reconcileFeedEquivalents(projector);
  const legacy = current.pages.find(page => !Array.isArray(page.identities));
  if (legacy) {
    const editor = new Editor(current.pages, projector, now);
    await editor.upgrade(legacy);
    return publish(manifest(await editor.persist(), now), projector);
  }
  const changes = await db.list<Change>('public_feed_changes', { limit:STEP_SIZE });
  // Reproject whole pages up to forty existing records; the cron cadence is unchanged.
  const due:PageRef[] = [];
  let policyKeys=0;
  if (projector.revision) for (const page of current.pages) {
    if (page.projectionRevision===projector.revision) continue;
    if (due.length && policyKeys+page.keys.length>STEP_SIZE) break;
    due.push(page);policyKeys+=page.keys.length;
  }
  if (!due.length) {
    const expired=current.pages.filter(page => page.refreshAt !== null && page.refreshAt <= now).sort((a,b) => a.refreshAt! - b.refreshAt!)[0];
    if (expired) due.push(expired);
  }
  if (!changes.items.length && !due.length) return readPublicFeedSummary();
  const wanted = new Map<string, { source:FeedSource; sourceId:string }>();
  for (const change of changes.items) {
    if (!allowedSource(change.source) || !change.sourceId) throw new Error('Invalid public feed change; reconciliation required');
    wanted.set(change.source + ':' + change.sourceId, change);
  }
  for (const page of due) for (const key of page.keys) {
    const colon = key.indexOf(':');
    wanted.set(key, { source:key.slice(0, colon) as FeedSource, sourceId:key.slice(colon + 1) });
  }
  const editor = new Editor(current.pages, projector, now);
  for (const source of new Set([...wanted.values()].map(item => item.source))) {
    const ids = [...wanted.values()].filter(item => item.source === source).map(item => item.sourceId);
    if (!ids.length) continue;
    const records = await db.get<Stored>(source, ids);
    if (records.length !== ids.length) throw new Error('Source read result count mismatch');
    for (let i = 0; i < ids.length; i++) await editor.put(source, ids[i], records[i]);
  }
  const result = await publish(manifest(await editor.persist(), now), projector);
  // Acknowledge only after the complete immutable manifest and visible pointer are durable.
  if (changes.items.length && !('regressionBlocked' in result && result.regressionBlocked)) {
    const removed = await db.delete('public_feed_changes', changes.items.map(change => change.id));
    if (removed.length !== changes.items.length || removed.some(ok => !ok)) throw new Error('Public feed change acknowledgement failed; retry remains idempotent');
  }
  return result;
}

// Collapse simultaneous reads of the same immutable public page within one
// runtime. No cross-request data is persisted or cached after completion.
const pageReadInFlight = new Map<string, Promise<Awaited<ReturnType<typeof readPublicFeedPageUncached>>>>();
export function readPublicFeedPage(cursor?:string) {
  const key = cursor ?? '__first__';
  const existing = pageReadInFlight.get(key);
  if (existing) return existing;
  const pending = readPublicFeedPageUncached(cursor).finally(() => {
    if (pageReadInFlight.get(key) === pending) pageReadInFlight.delete(key);
  });
  pageReadInFlight.set(key,pending);
  return pending;
}

async function readPublicFeedPageUncached(cursor?:string) {
  let manifestId:string | undefined;
  let page = 0;
  if (cursor?.startsWith('v2:')) {
    const match = /^v2:([A-Za-z0-9_-]{1,128}):(\d+)$/.exec(cursor);
    if (!match) throw new Error('Feed cursor invalid');
    manifestId = match[1];
    page = Number(match[2]);
  } else {
    if (cursor && !/^\d+$/.test(cursor)) throw new Error('Feed cursor invalid');
    page = Number(cursor || '0');
    manifestId = (await single<Control>('public_feed_control'))?.manifestId;
    if (!manifestId) manifestId = (await single<Control>('public_feed_last_good'))?.manifestId;
  }
  if (!Number.isSafeInteger(page) || page < 0 || page > 10000) throw new Error('Feed cursor invalid');
  if (!manifestId) return (await single<Stored>('public_feed_page_' + page)) ?? null;
  let [current] = await db.get<Manifest>('public_feed_manifests', [manifestId]);
  if (!current && !cursor?.startsWith('v2:')) {
    const backupId=(await single<Control>('public_feed_last_good'))?.manifestId;
    if (backupId && backupId!==manifestId) {
      const [backup]=await db.get<Manifest>('public_feed_manifests',[backupId]);
      if (backup) {
        console.warn('PUBLIC_FEED_RECOVERED_LAST_GOOD '+JSON.stringify({reason:'primary_manifest_missing'}));
        manifestId=backupId;
        current=backup;
      }
    }
  }
  if (!current) throw new Error('Public feed manifest missing');
  if (!Array.isArray(current.pages) || !Number.isSafeInteger(current.itemCount) || current.itemCount < 0) throw new Error('Public feed manifest corrupt');
  if (page >= Math.max(1, current.pages.length)) throw new Error('Feed cursor invalid');
  if (current.pages.length===0 && current.itemCount!==0) throw new Error('Public feed manifest count mismatch');
  let ref = current.pages[page];
  let [leaf] = ref ? await db.get<{ entries:Entry[] }>('public_feed_versions', [ref.id]) : [null];
  if (ref && !leaf && !cursor?.startsWith('v2:')) {
    const backupId=(await single<Control>('public_feed_last_good'))?.manifestId;
    if (backupId && backupId!==manifestId) {
      const [backup]=await db.get<Manifest>('public_feed_manifests',[backupId]);
      const backupRef=backup?.pages[page];
      const [backupLeaf]=backupRef ? await db.get<{entries:Entry[]}>('public_feed_versions',[backupRef.id]) : [null];
      if (backup && backupRef && backupLeaf) {
        console.warn('PUBLIC_FEED_RECOVERED_LAST_GOOD '+JSON.stringify({reason:'primary_page_missing'}));
        manifestId=backupId;
        current=backup;
        ref=backupRef;
        leaf=backupLeaf;
      }
    }
  }
  if (ref && !leaf) throw new Error('Public feed page missing');
  if (ref && leaf) {
    if (!Array.isArray(leaf.entries) || leaf.entries.length > PAGE_SIZE) throw new Error('Public feed page corrupt');
    if (!Array.isArray(ref.keys) || leaf.entries.length !== ref.keys.length) throw new Error('Public feed page count mismatch');
    if (leaf.entries.some((entry, index) => !entry || entry.key !== ref.keys[index])) throw new Error('Public feed page identity mismatch');
  }
  const { pages:_pages, schema:_schema, itemCount, ...summary } = current;
  const hasMore = page + 1 < current.pages.length;
  return { ...summary, items:leaf?.entries.map(entry => entry.item) ?? [], totalItems:itemCount,
    pageSize:PAGE_SIZE, hasMore, nextCursor:hasMore ? 'v2:' + manifestId + ':' + (page + 1) : undefined };
}


// Lookups must use the current public projection, never private source records.
export async function readPublicFeedItem(id:string) {
  if(!/^[A-Za-z0-9_-]{1,128}$/.test(id))return null;
  const current=await currentPublicFeedManifest();
  if(!current)return null;
  const ref=current.manifest.pages.find(page=>page.keys.some(key=>key.endsWith(':'+id)));
  if(!ref)return null;
  const [leaf]=await db.get<{entries:Entry[]}>('public_feed_versions',[ref.id]);
  if(!leaf)throw Error('Public feed page missing');
  if (!Array.isArray(leaf.entries) || !Array.isArray(ref.keys) || leaf.entries.length !== ref.keys.length) throw Error('Public feed page corrupt');
  return leaf.entries.find(entry=>entry.sourceId===id && ref.keys.includes(entry.key))?.item??null;
}

import { Buffer } from 'node:buffer';
import { createHash } from 'node:crypto';
import { publicPublisher, safePublicUrl } from './public-source-adapters';
const PUBLIC_CRAWLER='TrabajoCercaPublic/1.0';
type Policy={checkedAt:number;raw:string;error?:string;url:string;status:number;sha256?:string};
const publicPolicies=new Map<string,Policy>();

export function publicRobotsAllow(raw:string,address:string) {
  const groups:Array<{agents:string[];rules:Array<{path:string;allow:boolean}>}>=[];
  let group:{agents:string[];rules:Array<{path:string;allow:boolean}>} | null=null;
  let hasRules=false;
  for (const line of raw.split(/\r?\n/)) {
    const clean=line.replace(/#.*$/,'').trim(),colon=clean.indexOf(':');
    if (colon<0) continue;
    const key=clean.slice(0,colon).trim().toLowerCase(),value=clean.slice(colon+1).trim();
    if (key==='user-agent') {
      if (!group || hasRules) {group={agents:[],rules:[]};groups.push(group);hasRules=false;}
      group.agents.push(value.toLowerCase());
    } else if (group && ['allow','disallow'].includes(key)) {hasRules=true;if(value)group.rules.push({path:value,allow:key==='allow'});}
  }
  const scores=groups.map(value=>Math.max(-1,...value.agents.map(agent=>agent==='*'?0:PUBLIC_CRAWLER.toLowerCase().startsWith(agent)?agent.length:-1)));
  const best=Math.max(-1,...scores),url=new URL(address),path=url.pathname+url.search;
  const matches:Array<{allow:boolean;length:number}>=[];
  groups.forEach((value,index)=>{
    if (best<0 || scores[index]!==best) return;
    for (const rule of value.rules) {
      const end=rule.path.endsWith('$'),part=end?rule.path.slice(0,-1):rule.path;
      const pattern=part.split('*').map(text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('.*');
      if (new RegExp('^'+pattern+(end?'$':'')).test(path)) matches.push({allow:rule.allow,length:rule.path.replace(/[*$]/g,'').length});
    }
  });
  matches.sort((a,b)=>b.length-a.length || Number(b.allow)-Number(a.allow));
  return !matches.length || matches[0].allow;
}

export async function checkPublicRobots(address:string,now=Date.now()) {
  const origin=new URL(address).origin,publisher=publicPublisher(address);
  if (!publisher) return {allowed:false,error:'publisher_not_allowed'};
  let policy=publicPolicies.get(origin);
  if (!policy || now-policy.checkedAt>3600000) {
    let url=origin+'/robots.txt';
    policy={checkedAt:now,raw:'',url,status:0,error:'robots_policy_unavailable'};
    try {
      for (let attempt=0;attempt<4;attempt++) {
        const response=await fetch(url,{redirect:'manual',signal:AbortSignal.timeout(6500),headers:{'user-agent':PUBLIC_CRAWLER,'accept':'text/plain,text/html'}});
        policy.url=url;policy.status=response.status;
        if ([301,302,303,307,308].includes(response.status)) {
          const next=safePublicUrl(response.headers.get('location') || '',url);await response.body?.cancel();
          if (!next || publicPublisher(next)?.group!==publisher.group) break;
          url=next;continue;
        }
        if (response.status===404) {await response.body?.cancel();policy.error=undefined;break;}
        if (response.status!==200) {await response.body?.cancel();break;}
        const reader=response.body?.getReader(),parts:Uint8Array[]=[];let size=0;
        if (reader) for (;;) {
          const chunk=await reader.read();if(chunk.done)break;
          size+=chunk.value.byteLength;if(size>50000){await reader.cancel();throw new Error('policy_byte_limit');}parts.push(chunk.value);
        }
        else {const body=new Uint8Array(await response.arrayBuffer());if(body.length>50000)throw new Error('policy_byte_limit');parts.push(body);}
        const data=Buffer.concat(parts),mime=(response.headers.get('content-type') || '').split(';')[0].toLowerCase();
        policy.sha256=createHash('sha256').update(data).digest('hex');policy.raw=data.toString('utf8');
        if (mime!=='text/plain' && !(mime==='text/html' && /^\s*user-agent\s*:/im.test(policy.raw))) break;
        policy.error=undefined;break;
      }
    } catch { /* Unknown policy never grants access. */ }
    if (publicPolicies.size>=64) publicPolicies.delete(publicPolicies.keys().next().value!);
    publicPolicies.set(origin,policy);
  }
  const allowed=!policy.error && publicRobotsAllow(policy.raw,address);
  return {allowed,error:policy.error || (allowed?undefined:'robots_disallowed'),robotsUrl:policy.url,robotsHttp:policy.status,robotsSha256:policy.sha256};
}

export type PublicAdapter = {
  name:string;
  family:'portal' | 'local' | 'aggregator';
  identityUrl:string;
  verificationMethod:string;
};

