// Options are server-only. The HTTP route passes the request body as its first argument only.
export async function checkOneReview(body:unknown,options:{queuedJobId?:string}={}):Promise<ReviewCheck>{
 const input=body&&typeof body==='object'?body as Record<string,unknown>:{};
 const id=typeof input.id==='string'?input.id:'';
 const checkedAt=new Date().toISOString();
 const result=(status:ReviewCheck['status'],reason:string,extra:Partial<ReviewCheck>={}):ReviewCheck=>({status,reason,canPublish:false,checkedAt,...extra});
 if(!/^tc_[a-f0-9]{22}$/.test(id))return result('blocked','id_invalid');
 const [entry]=await db.get<Candidate>('radar_review_inbox',[id],{consistent:true});
 if(!entry||entry.kind!=='review_candidate'||typeof entry.url!=='string')return result('blocked','candidate_missing');
 const queued=options.queuedJobId==='tcq_'+id.slice(3)&&['submitting','queued_for_verification'].includes(entry.status||'');
 if(entry.status!=='ready_for_final_check'&&!queued)return result('blocked','mark_final_review_first');
 const save=async(value:ReviewCheck)=>{
  const [ok]=await db.tx.update('radar_review_inbox',[{id,record:{lastCheck:value,lastCheckedAt:checkedAt},if:{status:entry.status}}],{patch:true});
  if(!ok)throw Error('review_check_receipt_not_saved');return value;
 };
 const adapter=publicSourceAdapter(entry.url);
 if(!adapter||adapter.family==='aggregator')return save(result('blocked','primary_individual_source_required'));
 const page=await fetchPublicPage(entry.url,entry.url);
 const evidence={originalUrl:entry.url,finalUrl:page.url,httpStatus:page.status,sourceSha256:page.raw?createHash('sha256').update(page.raw).digest('hex'):null,checkedAt};
 const outcome=(status:ReviewCheck['status'],reason:string,extra:Partial<ReviewCheck>={})=>save(result(status,reason,{evidence,...extra}));
 if(page.error)return outcome('pending',page.error);
 const verification=evaluatePublicJob(entry.url,page.raw,page.url,page.status);
 if(verification.status==='rejected')return outcome('rejected',verification.reason);
 if(verification.status!=='verified'||!verification.source_published_at||!verification.work_commune||!verification.application)return outcome('pending',verification.reason);
 if((verification.company?.length||0)>2000||(verification.application?.length||0)>2000)return outcome('pending','source_field_budget_exceeded');
 const day=chileDay(new Date(verification.source_published_at)),today=chileDay(new Date(checkedAt));
 const age=Math.round((Date.parse(today+'T12:00:00Z')-Date.parse(day+'T12:00:00Z'))/86400000);
 if(!Number.isFinite(age)||age<0)return outcome('rejected','invalid_future_publication_date',{publishedDate:day});
 // Original publication age alone is not a rejection criterion; verify current source status instead.
 if(!TARGETS.has(verification.work_commune))return outcome('blocked','workplace_outside_territory');
 if(entry.territories?.length&&!entry.territories.includes(verification.work_commune))return outcome('blocked','workplace_conflicts_with_research');
 const identity=publicFeedIdentity(entry.url);
 if(!identity)return outcome('blocked','identity_unconfirmed');
 const fingerprint=['jobs-scan-v4',identity,fold(verification.title||''),fold(verification.company||''),verification.work_commune,verification.source_published_at,verification.application,options.queuedJobId||''].join('|');
 const now=Date.now(),prior=entry.duplicateScan,same=prior?.fingerprint===fingerprint;
 const started=Date.parse(prior?.startedAt||''),completed=Date.parse(prior?.completedAt||'');
 const completeRecent=Boolean(same&&Number.isFinite(completed)&&now>=completed&&now-completed<5*60000);
 // Keep incomplete scan checkpoints across cron cycles; restart stale scans after 24 hours.
 const runningRecent=Boolean(same&&!prior?.completedAt&&Number.isFinite(started)&&now>=started&&now-started<24*3600000);
 const saved=completeRecent||runningRecent?prior:undefined;
 const snapshot=await currentPublicFeedManifest();
 if(!snapshot)return outcome('pending','public_duplicate_catalog_unavailable');
 // The key/identity inventory remains stable during mere revalidation. No growing-table drain.
 const publicSignature=createHash('sha256').update(JSON.stringify(snapshot.manifest.pages.map(page=>[page.keys,page.identities]))).digest('hex');
 const samePublic=saved?.publicSignature===publicSignature;
 const matches=(x:Existing)=> (typeof x.url==='string'&&publicFeedIdentity(x.url)===identity)||Boolean(x.title&&x.company&&x.workCommunes?.includes(verification.work_commune!)&&fold(x.title)===fold(verification.title||'')&&fold(x.company)===fold(verification.company||''));
 if(!(completeRecent&&samePublic)){
  let publicCursor=samePublic?saved?.publicCursor||0:0,publicComplete=samePublic&&saved?.publicComplete===true;
  if(!publicComplete){
   const pages=snapshot.manifest.pages.slice(publicCursor,publicCursor+4);
   const leaves=pages.length?await db.get<{entries:Array<{source:string;sourceId:string;item:Existing&{id?:string}}>}>('public_feed_versions',pages.map(page=>page.id),{consistent:true}):[];
   if(leaves.some(leaf=>!leaf||!Array.isArray(leaf.entries)))return outcome('pending','public_duplicate_page_unavailable');
   for(const leaf of leaves)for(const value of leaf!.entries){
    if(value.source==='radar_jobs'&&value.sourceId===options.queuedJobId)continue;
    if(value.item.kind==='job_offer'&&matches(value.item))return outcome('blocked','already_in_public_catalog',{existingPublicId:value.item.id||value.sourceId});
   }
   publicCursor+=pages.length;publicComplete=publicCursor>=snapshot.manifest.pages.length;
  }
  let cursor=saved?.cursor||undefined,processed=saved?.processed||0,pages=saved?.pages||0,inventoryComplete=saved?.inventoryComplete===true;
  if(!inventoryComplete){
   const batch=await db.list<Existing>('radar_jobs',{limit:200,...(cursor?{nextToken:cursor}:{})});
   const duplicate=batch.items.find(x=>x.id!==options.queuedJobId&&!(queued&&x.discoveredBy==='admin-review-inbox-v1'&&x.review===true&&x.verified===false&&x.active===true&&x.id>options.queuedJobId!)&&(!x.kind||x.kind==='job_offer')&&matches(x));
   if(duplicate)return outcome('blocked','already_in_internal_inventory');
   if(batch.nextToken&&batch.nextToken===cursor)return outcome('pending','duplicate_scan_cursor_stalled');
   cursor=batch.nextToken;processed+=batch.items.length;pages++;inventoryComplete=!batch.nextToken;
  }
  const done=inventoryComplete&&publicComplete;
  const checkpoint:DuplicateScan={fingerprint,startedAt:saved?.startedAt||checkedAt,cursor:cursor||null,processed,pages,inventoryComplete,publicSignature,publicCursor,publicComplete,...(done?{completedAt:checkedAt}:{})};
  const [ok]=await db.tx.update('radar_review_inbox',[{id,record:{duplicateScan:checkpoint},if:{status:entry.status}}],{patch:true});
  if(!ok)return outcome('pending','duplicate_scan_concurrent_change');
  if(!done)return outcome('pending','duplicate_check_in_progress',{scanned:processed});
 }
 return outcome('verified_for_final_review',verification.reason,{title:verification.title,company:verification.company,workCommune:verification.work_commune,publishedDate:day,application:verification.application,sourcePublishedAt:verification.source_published_at,source:verification.source,deadline:verification.valid_through||null,verificationMethod:verification.verification_method,evidence:{...evidence,method:verification.verification_method}});
}

import { db, isAppDatabaseError } from '@appdeploy/sdk';
import {reviewPublicationReader} from './radar-review-queue';

// This private inbox is intentionally isolated from radar_jobs, radar_candidates and feed.
const TABLE='radar_review_inbox';
type Review={id?:string;kind:'review_candidate'|'review_catalog';url:string;sourceId:string;
  territories:string[];publishedEvidence:string|null;deadlineEvidence:string|null;
  status:'pending'|'needs_evidence'|'discarded'|'ready_for_final_check'|'submitting'|'queued_for_verification';
  radarJobId?:string;
  createdAt:string;updatedAt:string;published:false;verified:false;
  motorState?:string;blockReason?:string;lastCheckedAt?:string;nextCheckAt?:string;lastCheck?:{reason?:string}};
const HOSTS=new Set(['chiletrabajos.cl','kitempleo.cl','traiguencity.cl','malleco7.cl',
  'munimulchen.cl','municipalidadcollipulli.cl','municipalidadrenaico.cl',
  'muninegrete.cl','mtraiguen.cl','munilumaco.cl','munipuren.cl','muniercilla.cl','victoriachile.cl',
  'nacimiento.cl','munilossauces.cl','noticias.angol.cl','radionativa.cl',
  'radioviaducto.cl','lasnoticiasdemalleco.cl','bne.gob.cl','bne.cl','empleospublicos.cl','sence.gob.cl',
  'angolnoticiasnew.cl','computrabajo.com','cl.computrabajo.com','laborum.cl','cl.indeed.com',
  'hospitalangol.cl','opcionempleo.cl','trabajando.cl','linkedin.com','jobs.arauco.com','cmpc.csod.com','ssan.redsalud.gob.cl']);
const TOWNS=new Set(['Angol','Collipulli','Ercilla','Renaico','Mininco','Los Sauces','Purén',
  'Traiguén','Lumaco','Nacimiento','Negrete','Mulchén','Victoria']);
const short=(value:unknown,max=100)=>typeof value==='string'?value.trim().slice(0,max):'';
function safeUrl(value:unknown){
  const v=short(value,700);
  if(!v||v.length>600)return null;
  try{
    const u=new URL(v),h=u.hostname.replace(/^www\./,'').toLowerCase();
    if(u.protocol!=='https:'||u.username||u.password||u.port||!HOSTS.has(h))return null;
    u.hash='';return u.toString();
  }catch{return null;}
}
function dateEvidence(value:unknown){
  if(typeof value!=='string'||!/^20\d{2}-\d{2}-\d{2}$/.test(value))return null;
  const x=new Date(value+'T12:00:00Z');
  return !Number.isNaN(x.getTime())&&x.toISOString().slice(0,10)===value?value:null;
}
function parse(body:unknown){
  const obj=body&&typeof body==='object'?body as Record<string,unknown>:{};
  if(!Array.isArray(obj.items)||obj.items.length<1||obj.items.length>35)
    throw Error('Se requieren entre 1 y 35 referencias.');
  let rejected=0;const rows:Review[]=[];const unique=new Set<string>();
  const now=new Date().toISOString();
  for(const value of obj.items){
    const x=value&&typeof value==='object'?value as Record<string,unknown>:{};
    const key=short(x.candidate_key,40),url=safeUrl(x.url),status=short(x.status,80);
    if(!/^[a-f0-9]{22}$/.test(key)||!url||unique.has(key)||
      !['revision_obligatoria','revision_y_catalogo_no_disponible'].includes(status)){rejected++;continue;}
    unique.add(key);
    const places=Array.isArray(x.reported_territories)?x.reported_territories:[];
    const territories=[...new Set(places.filter((p):p is string=>typeof p==='string'&&TOWNS.has(p)))].slice(0,5);
    rows.push({id:'tc_'+key,kind:'review_candidate',url,sourceId:short(x.source_id,50),
      territories,publishedEvidence:dateEvidence(x.published_date_evidence),
      deadlineEvidence:dateEvidence(x.deadline_evidence),status:'pending',
      createdAt:now,updatedAt:now,published:false,verified:false});
  }
  return {rows,rejected};
}
async function prepare(){
  const existing=await db.list<Review>(TABLE,{limit:1});
  if(existing.items.length)return;
  // Initialize table catalog with standalone write before conditional chosen-ID writes.
  const now=new Date().toISOString();
  const [id]=await db.add(TABLE,[{kind:'review_catalog',url:'',sourceId:'',territories:[],
    publishedEvidence:null,deadlineEvidence:null,status:'pending',createdAt:now,
    updatedAt:now,published:false,verified:false}]);
  if(!id)throw Error('No fue posible iniciar la bandeja.');
}
export async function importReview(body:unknown){
  const {rows,rejected}=parse(body);
  if(!rows.length)return {inserted:0,duplicates:0,rejected,published:0};
  await prepare();
  let inserted=0,duplicates=0;
  for(const row of rows){
    const id=row.id!;
    const [old]=await db.get<Review>(TABLE,[id],{consistent:true});
    if(old){
      if(old.kind!=='review_candidate'||old.url!==row.url)throw Error('ID y URL no coinciden.');
      duplicates++;continue;
    }
    try{
      const [saved]=await db.tx.add(TABLE,[row]);
      if(saved)inserted++;else duplicates++;
    }catch(cause:unknown){
      if(isAppDatabaseError(cause)&&
        (cause.code==='AppDatabaseDuplicateId'||cause.code==='AppDatabaseUnknownOutcome')){
        const [existing]=await db.get<Review>(TABLE,[id],{consistent:true});
        if(existing&&existing.kind==='review_candidate'&&existing.url===row.url){duplicates++;continue;}
      }
      throw cause;
    }
  }
  return {inserted,duplicates,rejected,published:0};
}
export async function listReview(cursor?:string){
  if(cursor&&cursor.length>16000)throw Error('Cursor inválido.');
  const page=await db.list<Review>(TABLE,{limit:20,...(cursor?{nextToken:cursor}:{})});
  const reader=reviewPublicationReader();
  const items=[];
  for(const row of page.items.filter(x=>x.kind==='review_candidate')){
    const publication=await reader(row.id,row);
    items.push({id:row.id,url:row.url,sourceId:row.sourceId,territories:row.territories,
      publishedEvidence:row.publishedEvidence,deadlineEvidence:row.deadlineEvidence,status:row.status,
      radarJobId:row.radarJobId||null,motorState:row.motorState||null,
      lastCheckedAt:row.lastCheckedAt||null,nextCheckAt:row.nextCheckAt||null,
      lastCheck:row.lastCheck||null,publication});
  }
  return {schema:'trabajo-cerca.review-inbox.v1',items,hasMore:!!page.nextToken,nextToken:page.nextToken||null,
    scope:'current_page',summary:{queued:items.filter(x=>x.status==='queued_for_verification').length,
      published:items.filter(x=>x.publication.published).length,
      pending:items.filter(x=>['pending_verifier','waiting_for_feed','waiting_for_feed_projection'].includes(x.publication.state)).length,
      blocked:items.filter(x=>['blocked','duplicate','inactive_or_rejected','queue_reconciliation_required'].includes(x.publication.state)).length}};
}
export async function decideReview(body:unknown){
  const obj=body&&typeof body==='object'?body as Record<string,unknown>:{};
  const id=short(obj.id,50),status=short(obj.status,50);
  if(!/^tc_[a-f0-9]{22}$/.test(id)||
    !['needs_evidence','discarded','ready_for_final_check'].includes(status))
    throw Error('Decisión no válida.');
  const [item]=await db.get<Review>(TABLE,[id],{consistent:true});
  if(!item||item.kind!=='review_candidate')throw Error('Registro no encontrado.');
  if(item.status==='submitting'||item.status==='queued_for_verification')throw Error('Ya fue enviado al verificador.');
  const [updated]=await db.tx.update(TABLE,[{id,record:{
    status,updatedAt:new Date().toISOString(),published:false,verified:false,
    duplicateScan:undefined
  },if:{status:item.status}}],{patch:true});
  if(!updated)throw Error('Registro modificado: vuelve a cargar.');
  return {updated:true,status,published:false};
}
